   always @(posedge clk) begin
      if (rst) begin
         bitbuf <= 0; navail <= 0;
         code <= 0; first <= 0; index <= 0; len <= 4'd1;
         out_valid <= 1'b0; out_sym <= 8'b0;
      end
      else begin
         out_valid <= 1'b0;
         if (in_valid && in_ready) begin
            // append the incoming byte below the current valid field
            bitbuf <= bitbuf | ({8'b0, in_byte} << (8 - navail));
            navail <= navail + 5'd8;
            // NOTE: when navail==0 the shift (8-0)=8 places the byte at [15:8]
         end
         else if (have_bit) begin
            bitbuf <= bitbuf << 1;
            navail <= navail - 5'd1;
            if (match) begin
               out_valid <= 1'b1;
               out_sym   <= dsym_r;
               code <= 0; first <= 0; index <= 0; len <= 4'd1;
            end
            else begin
               code  <= code1 << 1;
               first <= (first + count) << 1;
               index <= index + count;
               len   <= len + 4'd1;
            end
         end
      end
   end

